async function openWardrobe(initial,mount){
 if(!mount){S.wardrobeInitial=initial;openSettingsDialog();return;}
 const root=document.createElement('section');root.id='ohana-wardrobe';mount.replaceChildren(root);let saved=null,avatar='',busy=false;
 const looks=wardrobeRoots().flatMap(wardrobeLooks);
 root.innerHTML=`<form class="wardrobe-form"><h2>Your Ohana character</h2><p>Every character and finished outfit is here. Choose your look.</p><label for="wardrobe-search">Find a character or outfit</label><input id="wardrobe-search" type="search" placeholder="Name, animal or outfit"><p id="wardrobe-status" role="status">Loading your saved look…</p><div class="wardrobe-gallery">${looks.map(id=>{const c=CHARACTERS[id];return `<button type="button" class="wardrobe-choice" data-look="${id}" aria-label="Choose ${esc(c.name+' '+(c.outfit||'original'))}" aria-pressed="false" disabled><img src="${esc(c.file)}" alt="" width="160" height="180" loading="lazy"><span>${esc(c.name)}</span><small>${esc(c.outfit||c.species||c.line||'')}</small></button>`;}).join('')}</div><details class="wardrobe-personality"><summary>Personality & nickname</summary><label>Character nickname<input id="wardrobe-nickname" maxlength="24"></label><label>Personality<select id="wardrobe-trait">${['Kindhearted','Playful','Brave','Curious','Calm','Helpful','Adventurous','Cheerful'].map(t=>`<option>${t}</option>`).join('')}</select></label><label>Their little saying<input id="wardrobe-motto" maxlength="80"></label></details><div class="wardrobe-actions"><button type="button" id="wardrobe-reset">Reset changes</button><button type="submit" id="wardrobe-save" disabled>Wear this look</button></div><p id="wardrobe-save-status" role="status"></p></form>`;
 const q=s=>root.querySelector(s),paint=()=>root.querySelectorAll('[data-look]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.look===avatar))),restore=()=>{avatar=CHARACTERS[saved?.avatar]?saved.avatar:'@hon';q('#wardrobe-nickname').value=saved?.wardrobe?.nickname||'';q('#wardrobe-trait').value=saved?.wardrobe?.trait||'Kindhearted';q('#wardrobe-motto').value=saved?.wardrobe?.motto||'';paint();};
 q('#wardrobe-search').oninput=e=>{const term=e.target.value.toLowerCase().trim();root.querySelectorAll('[data-look]').forEach(b=>{const c=CHARACTERS[b.dataset.look],base=CHARACTERS[c.base]||c;b.hidden=!`${c.name} ${base.name} ${base.species||''} ${c.outfit||''}`.toLowerCase().includes(term);});};
 root.querySelectorAll('[data-look]').forEach(b=>b.onclick=()=>{if(busy)return;avatar=b.dataset.look;paint();q('#wardrobe-save-status').textContent='Selected '+CHARACTERS[avatar].name+' '+(CHARACTERS[avatar].outfit||'');});q('#wardrobe-reset').onclick=()=>{if(!busy)restore();};
 q('form').onsubmit=async e=>{e.preventDefault();if(!saved||busy)return;busy=true;q('#wardrobe-save').disabled=true;try{saved=await api('/api/wardrobe',{avatar,nickname:q('#wardrobe-nickname').value.trim(),trait:q('#wardrobe-trait').value,motto:q('#wardrobe-motto').value.trim()});S.me.avatar=saved.avatar;S.av=saved.avatar;S.wardrobe=saved.wardrobe;localStorage.setItem('ohana_av',saved.avatar);q('#wardrobe-save-status').textContent='Saved. You are wearing this look.';try{await sync();}catch{}}catch(e){q('#wardrobe-save-status').textContent=e.message;}finally{busy=false;q('#wardrobe-save').disabled=false;}};
 try{saved=await api('/api/wardrobe');if(!root.isConnected)return;restore();if(initial&&CHARACTERS[initial]){avatar=initial;paint();}q('#wardrobe-status').textContent='';q('#wardrobe-save').disabled=false;root.querySelectorAll('[data-look]').forEach(b=>b.disabled=false);}catch(e){q('#wardrobe-status').textContent='Could not load your saved look. '+e.message;}
}

function openMemberProfile(id){
 id=Number(id);const member=id===Number(S.me?.id)?S.me:(S.sync?.members||[]).find(m=>Number(m.id)===id);
 if(!member||!ohanaDiscoverablePerson(member))return;
 const existing=document.querySelector('.ohana-member-profile');existing?.close();
 const d=document.createElement('dialog');d.className='ohana-member-profile';d.setAttribute('aria-labelledby','ohana-member-name');
 const self=id===Number(S.me?.id);
 d.innerHTML='<button type="button" data-profile-close aria-label="Close profile">✕</button><div class="member-character">'+(window.ohanaMemberPortrait?.markup(member.id,esc,{interactive:true})||avatarMarkup(member.avatar))+'</div><h2 id="ohana-member-name">'+esc(member.name)+'</h2>'+(member.about?'<p class="member-intro">'+esc(member.about)+'</p>':'')+'<div class="member-profile-actions">'+(self?'<button type="button" data-profile-edit>Edit</button>':'<button type="button" data-profile-message>Message</button><button type="button" data-profile-play>Play</button>')+'</div>';
 d.querySelector('[data-profile-close]').onclick=()=>d.close();
 d.querySelector('[data-profile-message]')?.addEventListener('click',()=>{d.close();openMemberDM(id);});
 d.querySelector('[data-profile-play]')?.addEventListener('click',()=>{d.close();openProfileGameChoice(member);});
 d.querySelector('[data-profile-edit]')?.addEventListener('click',()=>{d.close();openSettingsDialog();});
 document.body.append(d);d.addEventListener('close',()=>d.remove());d.showModal();
}
